package io.forgeloop.support.application;
import io.forgeloop.support.domain.*; import jakarta.transaction.Transactional; import java.util.UUID; import org.springframework.stereotype.Service;
@Service public class TicketCreationService { private final TicketRepository tickets; private final MemberRepository members; public TicketCreationService(TicketRepository tickets,MemberRepository members){this.tickets=tickets;this.members=members;} @Transactional public Ticket create(String actorId,String title){Member actor=members.findById(actorId).orElseThrow(()->new AssignmentForbiddenException("Unknown actor"));if(actor.getRole()!=Role.ADMIN)throw new AssignmentForbiddenException("Only an organization administrator may create tickets");String normalized=title==null?"":title.trim();if(normalized.isBlank()||normalized.length()>180)throw new IllegalArgumentException("Ticket title must be between 1 and 180 characters");return tickets.save(new Ticket("ticket-"+UUID.randomUUID(),normalized,actor.getOrganization()));} }
